import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"developers/api.md","filePath":"developers/api.md","lastUpdated":1793111003000}'),i={name:"developers/api.md"};function r(o,e,d,l,p,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>Community serves a versioned HTTP API under <code>/api/v1</code>. The installed server&#39;s OpenAPI schema is available at <code>/openapi.json</code>; use it for exact request fields and response shapes.</p><h2 id="start-a-run" tabindex="-1">Start a run <a class="header-anchor" href="#start-a-run" aria-label="Permalink to &quot;Start a run&quot;">​</a></h2><p>With a locally configured server running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8765/api/v1/runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Idempotency-Key: example-search-001&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;question&quot;:&quot;How does open-source funding affect maintenance?&quot;,&quot;source&quot;:&quot;openalex&quot;,&quot;search_budget&quot;:&quot;fast&quot;}&#39;</span></span></code></pre></div><p>The endpoint returns HTTP <strong>202</strong> with a run snapshot. Keep its run ID. Use a new idempotency key for a new intentional submission; reuse the same key only when retrying the same submission.</p><h2 id="follow-and-read-a-run" tabindex="-1">Follow and read a run <a class="header-anchor" href="#follow-and-read-a-run" aria-label="Permalink to &quot;Follow and read a run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/v1/runs/{run_id}</code></td><td>Current snapshot</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/events</code></td><td>Server-sent events</td></tr><tr><td>POST</td><td><code>/api/v1/runs/{run_id}/cancel</code></td><td>Request cancellation</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/results</code></td><td>Paginated results</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/citation-map</code></td><td>Citation graph</td></tr><tr><td>GET</td><td><code>/api/v1/runs/{run_id}/export?format=csv</code></td><td>Complete export</td></tr><tr><td>GET</td><td><code>/api/v1/history</code></td><td>Saved runs</td></tr></tbody></table><p>The schema also describes selection exports, artifacts, audit data, history deletion, and review projects/jobs.</p><p>SSE is a progress channel. If it disconnects, fetch the run snapshot and reconnect; do not submit a second search simply to restore progress. Cancellation is a request, not a guarantee that an in-flight upstream request stops instantly.</p><h2 id="client-implementation" tabindex="-1">Client implementation <a class="header-anchor" href="#client-implementation" aria-label="Permalink to &quot;Client implementation&quot;">​</a></h2><ul><li>Preserve the run ID and event sequence for recovery.</li><li>Follow response pagination instead of assuming all results arrive at once.</li><li>Handle queued, running, cancelling, and terminal states explicitly.</li><li>Render safe error codes and human-readable messages; do not expose secrets or raw upstream response bodies.</li><li>Treat result content and model-generated text as data, not executable markup.</li></ul><p>PaperSeek online shares the search contract but adds authentication, ownership, service modes, and credits. Its anonymous BYOK flow is not a general unauthenticated replacement for saved-run endpoints. Build against the deployment&#39;s own schema and auth flow.</p>`,13)])])}const m=t(i,[["render",r]]);export{c as __pageData,m as default};
